    [286266] = { enName = "Antonidas' Silver Coin", enDescription = "Grant me the strength to accept the things that I cannot change, the courage to change the things I can, and the wisdom to know the difference.", description = "Concedimi la forza di accettare le cose che non posso cambiare, il coraggio di cambiare quelle che posso e la saggezza di distinguere le une dalle altre." },
    [286268] = { enName = "Fandral Staghelm's Silver Coin", enDescription = "I pray that when the time comes, I will have the strength to thwart the forces beyond the gate.", description = "Prego che, quando arriverà il momento, avrò la forza di respingere le forze oltre il cancello." },
    [286274] = { enName = "Medivh's Silver Coin", enDescription = "<You sense the ringing of three tones in your head, the third barely audible under the others' din.>", description = "<Percepisci il suono di tre tonalità nella tua testa; la terza è appena udibile sotto il frastuono delle altre.>" },
    [286279] = { enName = "Anduin Wrynn's Gold Coin", enDescription = "I wish I would grow up, it feels like I've been 10 for years.", description = "Vorrei crescere, mi sembra di avere 10 anni da anni." },
    [286294] = { enName = "Valdrus Blackthorne's Gold Coin", enDescription = "Explain my dreams, little fountain. Why must I always be viewing my kin from above and moving them like pawns?", description = "Spiegami i miei sogni, piccola fontana. Perché devo sempre guardare i miei simili dall’alto e muoverli come pedine?" },
    [286298] = { enName = "Umbrinoth's Gold Coin", enDescription = "It seems my moonlighting days as a postal worker are coming to an end.", description = "A quanto pare, la mia attività part-time come portalettere sta per finire." },
    [286300] = { enName = "Sonya Darkhallow's Gold Coin", enDescription = "This doesn't make sense. Why am I putting a coin in a fountain?", description = "Non ha senso. Perché sto mettendo una moneta in una fontana?" },
    [286302] = { enName = "Zarla Ober's Gold Coin", enDescription = "The amount of coins shining in the pool.. Maybe no one will notice if I take just one.", description = "Quante monete brillano nella vasca... Forse nessuno si accorgerà se ne prendo solo una." },
    [286314] = { enName = "Squire Rowan's Copper Coin", enDescription = "I wish people would stop knocking my toys off the shelf.", description = "Vorrei che la gente smettesse di buttare giù i miei giocattoli dallo scaffale." },
    [286315] = { enName = "Rath'mael's Copper Coin", enDescription = "I could have used this copper for something productive. Perhaps something with string and a machine.", description = "Avrei potuto usare questo rame per qualcosa di produttivo. Magari qualcosa con uno spago e una macchina." },
    [286316] = { enName = "Mason's Copper Coin", enDescription = "It's not even magical here.", description = "Qui non c’è nemmeno magia." },
    [286317] = { enName = "Ofalo's Copper Coin", enDescription = "How does a tavern run out of ale!", description = "Come fa una taverna a rimanere senza birra!" },
    [286318] = { enName = "Sair's Copper Coin", enDescription = "I miss my sword and shield. I feel so naked without my sword and shield.", description = "Mi mancano la spada e lo scudo. Mi sento così nudo senza la mia spada e il mio scudo." },
    [286327] = { enName = "Rhonin's Gold Coin", enDescription = "Here you go Nozdormu. What was I supposed to do after this?", description = "Ecco a te, Nozdormu. Cosa dovevo fare dopo?" },
    [286328] = { enName = "Elaadrin Evengale's Silver Coin", enDescription = "How do I prove they copied us with this fountain.", description = "Come faccio a dimostrare che ci hanno copiati con questa fontana?" },
}
for id, record in pairs(records) do
    local current = ns.data.itemDescriptionOverrides[id]
    if current == nil then
        ns.data.itemDescriptionOverrides[id] = record
    end
end
